export function qbCtx(){ let st=stageOf(); if(st==='entry') st='subj'; return {st,open:APP.open,lsub:APP.lsub,beKind:APP.beKind,side:APP.side,subjTab:APP.subjTab,active:APP.active}; }
export function qbRes1(q){ const ctx=qbCtx(); const keep=APP.search; APP.search={q,ctx}; try{ return searchResults(); }catch(e){ return []; } finally{ APP.search=keep; } }
