 const done=(()=>{ try{ return sentenceComplete(APP.S); }catch(e){ return false; } })();
 if(APP.open==='cw') return '👉 どんな文を続ける？（where / what / if など）／ だれを・何を（him など）';
 if(st==='extras'){ const L=optionalLeft(kind).map(cd).filter(Boolean).slice(0,3).join('・'); return done? ('✅ できた'+(L?'　続けるなら：'+L:'')) : (L||''); }
 if(st==='subj') return '👉 だれが？ 何が？';
